uniform shader Noise;
uniform float4 Res;
uniform float4 Clock;
uniform float4 Acc;
uniform float4 Turn;
uniform float4 Aura;
uniform float4 Reveal;
uniform float4 Waves[12];

// value noise from the texture: 64 cells across it, -1..1; the lookup stays between the first and last texel centres (never in the half texel at the edge)
float noise(float2 p) { return Noise.eval((fract(p / 64.0) * (511.0 / 512.0) + 0.5 / 512.0) * 512.0).r * 2.0 - 1.0; }

float fbm(float2 p)
{
    float s = 0.0, a = 0.5;
    for (int i = 0; i < 3; i++) { s += a * noise(p); p = p * 1.9 + float2(1.7, 9.2); a *= 0.42; }
    return s * 1.6;
}

float form(float2 p, float t)
{
    float2 q = float2(fbm(p + float2(0.0, t)), fbm(p + float2(5.2, 1.3) - t * 0.7));
    float2 r = float2(fbm(p + 1.5 * q + float2(1.7, 9.2) + t * 0.5), fbm(p + 1.5 * q + float2(8.3, 2.8) - t * 0.4));
    return fbm(p + 1.3 * r);
}

float3 thermal(float v)
{
