    float3 c = float3(0.006, 0.008, 0.016);
    c = mix(c, float3(0.02, 0.10, 0.075), smoothstep(0.16, 0.34, v));
    c = mix(c, violet, smoothstep(0.34, 0.50, v));
    c = mix(c, float3(1.0, 0.33, 0.66), smoothstep(0.52, 0.64, v));
    c = mix(c, float3(1.0, 0.56, 0.30), smoothstep(0.64, 0.76, v));
    c = mix(c, float3(1.0, 0.82, 0.66), smoothstep(0.76, 0.88, v));
    c = mix(c, float3(1.0, 0.97, 0.92), smoothstep(0.88, 1.0, v));
    return c;
}

half4 main(float2 fc)
{
    float2 uv = fc / Res.xy;
    float2 asp = float2(Res.x / Res.y, 1.0);
    float2 pos = uv * asp;

    float2 rv = float2(1.0, 0.0);
