    float mG = clamp(mask * (m0 + form(p, t) * 1.55) - 0.14 + heat * 0.45, 0.0, 1.0);
    float mB = clamp(mask * (m0 + form(p - off, t) * 1.55) - 0.14 + heat * 0.45, 0.0, 1.0);
    float3 col = float3(thermal(mR).r, thermal(mG).g, thermal(mB).b);
    float hx = (mG - 0.53) / 0.02;
